using Forjix.Api.Authorization;using Forjix.Application.Common;using Forjix.Application.Features.Settings;using Microsoft.AspNetCore.Mvc;namespace Forjix.Api.Controllers;[ApiController,Route("api/settings")]public sealed class SettingsController(ISettingsService service):ControllerBase{[HttpGet,RequirePermission(Permissions.SettingsView)]public async Task<ActionResult<TenantSettingsView>>Get(CancellationToken ct)=>Ok(await service.GetAsync(ct));[HttpPut,RequirePermission(Permissions.SettingsManage)]public async Task<ActionResult<TenantSettingsView>>Put(UpdateTenantSettingsRequest r,CancellationToken ct)=>Ok(await service.UpdateAsync(r,ct));[HttpPost("logo"),RequestSizeLimit(2_097_152),RequirePermission(Permissions.SettingsManage)]public async Task<IActionResult>Logo(IFormFile file,CancellationToken ct){if(file.Length==0||file.Length>2_097_152)throw new RequestValidationException("A logo deve ter até 2 MB.");await using var stream=file.OpenReadStream();await service.UploadLogoAsync(stream,file.ContentType,Path.GetExtension(file.FileName),ct);return NoContent();}[HttpGet("logo"),RequirePermission(Permissions.SettingsView)]public async Task<IActionResult>Logo(CancellationToken ct){var file=await service.GetLogoAsync(ct);return file is null?NotFound():File(file.Content,file.ContentType);}}
